from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
def read(p): return (ROOT/p).read_text()
def load(p): return json.loads(read(p))
def test_m275_release_and_contract():
 d=load('data/release_identity.json'); assert d['milestone'] in {'M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and d['client_version'] in {'0.275.0','0.276.0','0.277.0','0.278.0','0.279.0','0.280.0','0.281.0','0.282.0','0.283.0','0.284.0','0.285.0','0.286.0','0.287.0','0.288.0','0.289.0','0.290.0','0.291.0','0.292.0','0.293.0','0.294.0','0.295.0','0.296.0','0.297.0','0.298.0','0.299.0','0.300.0','0.301.0'} and d['build_number'] in {275,276,277,278,279,280,281,282,283,284,285,286,287,288,289,290,291,292,293,294,295,296,297,298,299,300,301} and d['content_config_version'] in {'M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and d['master_concept']=='V3.8'
 c=load('data/m275_authoritative_loot_distribution_contract.json'); assert c['contract']=='authoritative_loot_table_drop_pool_group_fleet_reward_distribution_foundation'; assert c['genre_ux_references']==['Seafight','Battle of Sea']; assert all(x in c['authority']['server_owns'] for x in ['loot_pool_selection','drop_roll_resolution','rarity_resolution','personal_drop_assignment','group_reward_distribution','fleet_reward_distribution','settlement_authorization'])
def test_m275_runtime_fail_closed_and_revision_guarded():
 s=read('scripts/online/m275_authoritative_loot_distribution_runtime.gd')
 for t in ['bind_reward_eligibility','ingest_server_loot_snapshot','ingest_server_loot_event','loot_revision','distribution_revision','settlement_sequence','pool_context','resolved_drop_state','participant_distribution','group_distribution','fleet_distribution','settlement_authorizations','invalidate_from_world_resync']: assert t in s
 for t in ['can_client_select_loot_pool() -> bool: return false','can_client_roll_drop() -> bool: return false','can_client_assign_personal_drop() -> bool: return false','can_client_split_group_reward() -> bool: return false','can_client_split_fleet_reward() -> bool: return false','can_client_override_rarity() -> bool: return false','can_client_authorize_settlement() -> bool: return false','can_client_create_reward_instance() -> bool: return false','can_client_confirm_settlement() -> bool: return false','can_client_transfer_test_loot_to_global() -> bool: return false']: assert t in s
 assert 'lr <= loot_revision' in s and 'seq <= settlement_sequence' in s and '"can_settle":false' in s
def test_m275_bootstrap_deck_admin_dependencies():
 b=read('scripts/core/game_bootstrap.gd'); deck=read('scripts/ui/command_deck.gd'); assert 'M275AuthoritativeLootDistributionRuntime.new()' in b and 'AuthoritativeLootDistributionReadiness' in b; assert 'LOOT TABLES · DROP POOLS · GROUP / FLEET DISTRIBUTION' in deck and 'M275AuthoritativeLootDistributionCatalog.settlement()' in deck
 a=load('data/admin_content_type_registry.json'); assert a['milestone'] in {'M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and all(x in a['content_types'] for x in ['loot_table_policy_definition','drop_pool_policy_definition','group_fleet_reward_distribution_policy_definition','loot_settlement_authorization_policy_definition'])
 c=load('data/m275_authoritative_loot_distribution_contract.json'); assert c['dependencies']['eligibility'].startswith('M274') and c['dependencies']['encounter'].startswith('M273') and c['dependencies']['settlement'].startswith('M266')
def test_m275_convergence_and_unset_tuning():
 m=load('data/m239_master_convergence_matrix.json'); assert m['milestone'] in {'M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'}; row={x['domain']:x for x in m['domains']}['authoritative_loot_table_drop_pool_group_fleet_reward_distribution']; assert row['status']=='PARTIAL' and 'm275_fix' in row and any(x.startswith('production authoritative loot-table') for x in row['remaining'])
 c=load('data/m275_authoritative_loot_distribution_contract.json'); assert all(x in c['unset_until_measured'] for x in ['drop_probabilities','rarity_weights','pity_rules','group_share_formula','fleet_share_formula','reward_values'])
